import { DomainModels, StudioProApi } from "@mendix/extensions-api";
import { Agent, Variable } from "../types/agent";
import { createStudioProLogger } from "../config/logger";


export function createNewAgent(): Agent {
    return {
        description: "",
        entity: "",
        systemPrompt: "",
        userPrompt: "",
        usageType: "Task",
        variables: [],
        tools: []
    };
};


export function calculateVariables(studioPro: StudioProApi, agent: Agent): Promise<Variable[]> {

    const systemPromptPlaceholders = agent.systemPrompt.match(/\{\{([^}]+)\}\}/g) || [];
    const userPromptPlaceholders = agent.userPrompt ? agent.userPrompt.match(/\{\{([^}]+)\}\}/g) || [] : [];

    const placeholders: string[] = [...systemPromptPlaceholders, ...userPromptPlaceholders];

    if (placeholders.length === 0) {
        return Promise.resolve([]);
    }

    // The keys are only the part between {{}}
    const variableKeys: string[] = placeholders.map(match =>
        match.replace(/\{\{|\}\}/g, '')
    );

    // Remove duplicates
    const uniqueVariableKeys: string[] = [...new Set(variableKeys)];

    // Get or create Variable objects (keep the ones that already exist on the current agent)
    const currentVariables: Variable[] = agent.variables;
    const newVariables: Variable[] = uniqueVariableKeys.map(name => {
        const existingVariable = currentVariables.find(v => v.key === name);
        return existingVariable || {
            key: name,
            isAttributeInEntity: false,
            backgroundColor: '',
            borderColor: '',
            testValue: ''
        };
    });

    // Return variables with the color code fields updated and check for match with entity attributes.
    const newVariablesWithColor = setColors(newVariables);
    return checkAttributes(studioPro, newVariablesWithColor, agent);
};


export const createHighlightRules = (variables: Variable[]) => {
    return variables.map(v => ({
        pattern: new RegExp('\\{\\{' + v.key + '\\}\\}', 'g'),
        style: {
            color: v.borderColor,
            backgroundColor: v.backgroundColor,
            border: `1px solid ${v.borderColor}`,
            borderRadius: '2px',
            margin: '0 -1px'
        }
    }));
};


function setColors(variables: Variable[]): Variable[] {
    // Color set from Figma design: [BackgroundColor, BorderColor]
    const colorPalette: string[][] = [
        ['#DCEEFE', '#0123C6'], // Blue
        ['#E2E0FC', '#4701D4'], // Purple
        ['#F7E0FF', '#780194'], // Violet
        ['#FFE5E9', '#9E051B'], // Red
        ['#FFF2CF', '#803600'], // Yellow
        ['#E1FAE1', '#076407'], // Green
    ] as const;

    return variables.map((variable, index) => ({
        ...variable,
        backgroundColor: colorPalette[index % colorPalette.length][0],
        borderColor: colorPalette[index % colorPalette.length][1]
    }));
};


export async function checkAttributes(studioPro: StudioProApi, variables: Variable[], agent: Agent): Promise<Variable[]> {
    const isEntityFound = await isAgentEntityFound(studioPro, agent);
    const attributeNames: string[] = await getAttributeNames(agent, studioPro);
    return variables.map(variable => {
        const isAttributeInEntity = attributeNames.includes(variable.key);
        return {
            ...variable,
            isAttributeInEntity: isEntityFound === false || isAttributeInEntity,
        }
    })
};


export const isAgentEntityFound = async (studioPro: StudioProApi, agent: Agent): Promise<boolean> => {
    if (!agent.entity) {
        return true;
    }
    return getEntity(studioPro, agent.entity) != undefined;
};


export const getEntity = async (studioPro: StudioProApi, entityQualifiedName: string): Promise<DomainModels.Entity | undefined> => {
    const [moduleName, entityName] = entityQualifiedName.split('.');
    if (!moduleName || !entityName) {
        return undefined;
    }
    const domainModel = await studioPro.app.model.domainModels.getDomainModel(moduleName);
    return domainModel?.getEntity(entityName);
};


const getGeneralization = async (studioPro: StudioProApi, entity: DomainModels.Entity): Promise<DomainModels.Entity | undefined> => {
    const logger = createStudioProLogger(studioPro);
    const generalization = entity.generalization as DomainModels.Generalization;
    const generalizationEntity = await getEntity(studioPro, generalization.generalization);

    if (!generalizationEntity) {
        logger.error(`Generalization entity ${generalization.generalization} not found.`);
        return undefined;
    }

    return generalizationEntity;
};


export const isPersistableEntity = async (entity: DomainModels.Entity, studioPro: StudioProApi): Promise<boolean | undefined> => {
    if (entity.generalization.$Type === "DomainModels$NoGeneralization") {
        const noGeneralization = entity.generalization as DomainModels.NoGeneralization;
        return noGeneralization.persistable;
    }

    // Recursive case: has generalization
    const generalizationEntity = await getGeneralization(studioPro, entity);

    if (!generalizationEntity) {
        return undefined;
    }

    // Recursively check the generalization
    return isPersistableEntity(generalizationEntity, studioPro);
};


export const getMissingAttributes = async (studioPro: StudioProApi, agent: Agent): Promise<string[]> => {
    if (agent.variables.length === 0) {
        return [];
    }
    if (!agent.entity || !(await getEntity(studioPro, agent.entity))) {
        return [];
    }
    return agent.variables.filter(v => !v.isAttributeInEntity).map(v => v.key);
};


const getAttributeNames = async (agent: Agent, studioPro: StudioProApi): Promise<string[]> => {
    if (!agent.entity) {
        return [];
    }
    const entity = await getEntity(studioPro, agent.entity);
    if (!entity) {
        return [];
    }
    return getEntityAttributeNames(studioPro, entity);
};


export const getUnusedAttributes = async (studioPro: StudioProApi, agent: Agent): Promise<string[]> => {
    const attributeNames: string[] = await getAttributeNames(agent, studioPro);
    return attributeNames.filter(a => !(agent.variables.find(v => v.key === a)));
};


const getEntityAttributeNames = async (studioPro: StudioProApi, entity: DomainModels.Entity): Promise<string[]> => {

    // Entity is top-level in terms of inheritance, i.e. has no generalization
    if (entity.generalization.$Type === "DomainModels$NoGeneralization") {
        return entity.attributes.map(a => a.name);
    }

    // Recursive case: has generalization

    const generalizationEntity = await getGeneralization(studioPro, entity);

    if (!generalizationEntity) {
        return entity.attributes.map(a => a.name);
    }

    const inheritedAttributes = await getEntityAttributeNames(studioPro, generalizationEntity);
    return entity.attributes.map(a => a.name).concat(inheritedAttributes);
};
